cards.solution:
public class Main {
    public static void main(String[] args) {
        int peserta = 45;
        int kapasitas = 12;
        int bus = (int) Math.ceil((double) peserta / kapasitas);
        System.out.println(bus);
        System.out.println((int) Math.pow(3, 4));
    }
}

